racter"},{"op":"ratio","den":"chars","key":"cost_per_1k_chars","num":["cost"],"unit":"usd","label":"Cost per 1,000 characters","scale":1000},{"of":"embedding_cost_usd","op":"sum","key":"embedding_cost","unit":"usd","label":"Embedding cost","additive":true},{"of":"extraction_cost_usd","op":"sum","key":"extraction_cost","unit":"usd","label":"Extraction cost","additive":true},{"of":"cleanup_cost_usd","op":"sum","key":"cleanup_cost","unit":"usd","label":"Cleanup cost","additive":true},{"of":"enrichment_cost_usd","op":"sum","key":"enrichment_cost","unit":"usd","label":"Enrichment cost","additive":true},{"of":"embedding_cost_saved_usd","op":"sum","key":"embedding_saved","unit":"usd","label":"Embedding cost saved by the cache","additive":true},{"of":"embedding_cache_hits","op":"sum","key":"cache_hits","unit":"count","label":"Embedding cache hits","additive":true},{"of":"embedding_calls","op":"sum","key":"embedding_calls","unit":"count","label":"Embedding calls","additive":true},{"op":"ratio","den":["cache_hits","embedding_calls"],"key":"cache_hit_rate","num":["cache_hits"],"unit":"share","label":"Embedding cache-hit rate"},{"of":"total_cost_usd","op":"sum","key":"cost_enriched","unit":"usd","label":"Cost of successful enriched runs","where":{"status":"success","enrich_ran":true},"additive":true},{"op":"count","key":"runs_enriched","unit":"count","label":"Successful enriched runs","where":{"status":"success","enrich_ran":true},"additive":true},{"of":"total_cost_usd","op":"sum","key":"cost_plain","unit":"usd","label":"Cost of successful runs without enrichment","where":{"status":"success","enrich_ran":false},"additive":true},{"op":"count","key":"runs_plain","unit":"count","label":"Successful runs without enrichment","where":{"status":"success","enrich_ran":false},"additive":true},{"op":"ratio","den":"runs_enriched","key":"avg_cost_enriched","num":["cost_enriched"],"unit":"usd","label":"Average successful enriched run"},{"op":"ratio","den":"runs_plain","key":"avg_cost_plain","num":["cost_plain"],"unit":"usd","label":"Average successful run without enrichment"},{"op":"ratio","den":"avg_cost_plain","key":"enrichment_multiplier","num":["avg_cost_enriched"],"unit":"times","label":"Enrichment multiplier"},{"of":"total_cost_usd","op":"rate","key":"monthly_projection","per":"month","unit":"usd","label":"Projected monthly cost","additive":false},{"of":"total_cost_usd","op":"rate","key":"monthly_projection_10x","per":"month","unit":"usd","label":"Projected monthly cost at 10× the load","scale":10,"additive":false},{"of":"chunks_written","op":"sum","key":"chunks_written","unit":"count","label":"Chunks written","additive":true},{"of":"chunks_reused","op":"sum","key":"chunks_reused","unit":"count","label":"Chunks reused","additive":true},{"of":"duration_ms","op":"median","key":"duration_median","unit":"ms","label":"Median duration","additive":false},{"of":"organization_id","op":"count_distinct","key":"organizations","unit":"count","label":"Organizations","additive":false}],"dimensions":[{"key":"source_kind","from":"source_kind","kind":"choice","label":"Source kind","choices":[{"label":"Note","value":"note"},{"label":"Transcript","value":"transcript"},{"label":"Scraped page","value":"scrape_parsed_page"},{"label":"Web page","value":"web_page"},{"label":"File","value":"cld_file"},{"label":"Source","value":"processed_document"},{"label":"Inline text","value":"inline"}],"cardinality":"low","empty_label":"No source kind"},{"key":"status","from":"status","kind":"choice","label":"Status","choices":[{"label":"Succeeded","value":"success"},{"label":"Skipped","value":"skipped"},{"label":"Errored","value":"error"},{"label":"Partly done","value":"partial"},{"label":"Still running","value":"running"}],"cardinality":"low","empty_label":"No status"},{"key":"triggered_by","from":"triggered_by","kind":"choice","label":"Started by","choices":[{"label":"Saved by a person","value":"save_hook"},{"label":"Landed from a source","value":"landing"},{"label":"Source intelligence","value":"source_intelligence"},{"label":"Backfill","value":"backfill"},{"label":"Started by hand","value":"manual"}],"cardinality":"low","empty_label":"Not known"},{"key":"urgency","from":"urgency","kind":"choice","label":"Urgency","choices":[{"label":"Batch (cheaper, later)","value":"batch"},{"label":"Automatic","value":"auto"},{"label":"Live","value":"live"}],"cardinality":"low","empty_label":"Not known"},{"key":"enrich_ran","from":"enrich_ran","kind":"boolean","label":"Enrichment ran"},{"key":"cost_is_exact","from":"cost_is_exact","kind":"boolean","label":"Cost is exact"},{"key":"embedding_model","from":"embedding_model","kind":"choice","label":"Embedding model","cardinality":"low","empty_label":"No embedding (nothing new to embed)"},{"key":"organization","from":"organization_id","kind":"relation","label":"Organization","relation":{"token":"organization"},"empty_label":"No organization"},{"key":"person","from":"actor_id","kind":"relation","label":"Person","relation":{"token":"user","person":true},"empty_label":"No person"},{"key":"at","from":"started_at","kind":"time","label":"Started","grains":["year","quarter","month","week","day","hour"]}],"lane_columns":{"organization":"organization_id"}}$drill$::jsonb;
